"""Atlas del Éxodo: lugares (Escritura · Arqueología · Hoy), tramos del camino y rutas antiguas.

«biblia» admite claves de los pasajes de datos.py (se resuelven con su traducción) o pares [cita, texto].
Las citas de la biblioteca de Yada («bib») se agregan desde /home/claude/work/bib_atlas.json
al generar (ver datos.py), y quedan escritas en atlas.json.
Coordenadas: [lat, lon]. Las identificaciones discutidas se señalan como tales.
"""
from hitos import (HUIDA, A_HOREB, RAMSES_SUCOT, SUCOT_ETAM, ETAM_PIHA, CRUCE, A_MARA, MARA_ELIM, ELIM_SIN, SIN_DOFCA, DOFCA_REF,
                   REF_SINAI, SINAI_HAZ, HAZ_CADES, CADES_HOR, HOR_PUNON, PUNON_ARNON, ARNON_MOAB, REY, HORUS)

def L(id, n, ll, k, actual, biblia=(), arq=(), hoy="", he="", site=None, fuentes=()):
    return {"id": id, "site": site if site is not None else id, "n": n, "he": he, "ll": ll, "k": k, "actual": actual,
            "biblia": list(biblia), "arq": list(arq), "hoy": hoy, "fuentes": list(fuentes)}

